package br.com.sussmartcare.patientjourney.domain; import static org.assertj.core.api.Assertions.assertThat; import java.util.*; import org.junit.jupiter.api.Test;
class VisitEventSourcingTest {@Test void rehydratesSameStateFromEvents(){UUID patient=UUID.randomUUID(),facility=UUID.randomUUID();var visit=Visit.create(patient,facility,Channel.MOBILE);visit.recordPreAnamnesis("Sintomas informados pelo paciente");visit.checkIn();var events=visit.pullChanges();var rebuilt=Visit.rehydrate(events);assertThat(rebuilt.getId()).isEqualTo(visit.getId());assertThat(rebuilt.getPatientId()).isEqualTo(patient);assertThat(rebuilt.getStatus()).isEqualTo(VisitStatus.WAITING_TRIAGE);assertThat(rebuilt.getPreAnamnesis()).isEqualTo("Sintomas informados pelo paciente");assertThat(rebuilt.getVersion()).isEqualTo(3);}}
